   XmlDocument  xmlDoc = new XmlDocument();
   dynamic data = JsonConvert.DeserializeObject(requestBody);
   string params1 = data?.Parameters[1];
   //log.LogInformation(params1);
xmlDoc.LoadXml(params1);

    return new OkObjectResult("<?xml version=\"1.0\" encoding=\"utf-8\"?>"+"<ManifestContainerResponse xmlns=\"http://www.manh.com/ILSNET/Shipping/ManifestContainerResponse\" xmlns:xs=\"http://www.w3.org/2001/XMLSchema\">"+
    "  <Result>"+
    "    <SuccessFlag xmlns=\"http://www.manh.com/ILSNET/General/Result\">true</SuccessFlag>"+
    "  </Result>"+
    "  <Parcels>"+
    BuildParcel(xmlDoc)
    +
    "  </Parcels>"+"  <AccessorialCharge>0</AccessorialCharge>"+
    "  <BaseFreightCharge>10</BaseFreightCharge>"+"  <FreightDiscount>0</FreightDiscount>"+
    "  <TotalFreightCharge>10</TotalFreightCharge>"+   
    "</ManifestContainerResponse>"); 
}

                
            
        
    


            
        
    
    

